$ErrorActionPreference='Stop'
$outbox='C:\Users\jm076\AppData\Local\Temp\LavaFacil-CorreoPedidos-2026-11-06\outbox';$s=New-Object Microsoft.PowerShell.Commands.WebRequestSession
function Req($m,$p,$b=$null,$h=@{}){$hh=@{};foreach($x in $h.GetEnumerator()){$hh[$x.Key]=$x.Value};try{$x=Invoke-WebRequest -UseBasicParsing -WebSession $s -Method $m -Uri ('http://127.0.0.1:5088'+$p) -Headers $hh -ContentType 'application/json' -Body $(if($null -ne $b){$b|ConvertTo-Json -Compress}else{$null});[pscustomobject]@{Status=[int]$x.StatusCode;Body=$x.Content}}catch{if($_.Exception.Response){$q=$_.Exception.Response;$rd=New-Object IO.StreamReader($q.GetResponseStream());[pscustomobject]@{Status=[int]$q.StatusCode;Body=$rd.ReadToEnd()}}else{throw}}}
$checks=@();function C($n,$ok,$d){$script:checks+=[pscustomobject]@{prueba=$n;estado=if($ok){'PASS'}else{'FAIL'};detalle=$d}}
$b=Req 'GET' '/api/bootstrap';$token=($b.Body|ConvertFrom-Json).token;C 'bootstrap' ($b.Status -eq 200 -and ($b.Body|ConvertFrom-Json).correoConfigurado) "status=$($b.Status)"
$stamp=[DateTime]::UtcNow.ToString('yyyyMMddHHmmss');$u="autopedido$stamp";$e="$u@example.com";# Clave de fixture generada en tiempo de ejecución; no se versiona ningún valor real.
$pw=if($env:LAVAFACIL_TEST_PASSWORD){$env:LAVAFACIL_TEST_PASSWORD}else{'Temporal-'+[guid]::NewGuid().ToString('N')+'!Aa1'};$r=Req 'POST' '/api/register' @{identity="CP-$stamp";name='AUTO';lastName='PEDIDO';phone='5551234567';email=$e;address='prueba';username=$u;password=$pw} @{'X-CSRF-TOKEN'=$token};C 'registro cliente prueba' ($r.Status -eq 200) "status=$($r.Status)"
$b=Req 'GET' '/api/bootstrap';$token=($b.Body|ConvertFrom-Json).token;$sv=Req 'GET' '/api/services';Set-Content "$PSScriptRoot\services-response.json" $sv.Body;$svc=@(($sv.Body|ConvertFrom-Json).Rows);$line=$svc|Where-Object{$_.Activo -ne $false -and $_.IdServicio}|Select-Object -First 1;if(-not $line){$line=$svc|Select-Object -First 1};C 'catalogo servicio' ($sv.Status -eq 200 -and $null -ne $line) "status=$($sv.Status); servicio=$($line.IdServicio)"
$r=Req 'POST' '/api/orders' @{clientId=$null;notes='CorreoPedidos evidencia';lines=@(@{serviceId=[int]$line.IdServicio;quantity=1})} @{'X-CSRF-TOKEN'=$token};$order=$r.Body|ConvertFrom-Json;C 'crear pedido flujo web' ($r.Status -eq 200) "status=$($r.Status); body=$($r.Body)";$orderId=if($order.Rows){$order.Rows[0].IdPedido}else{$order[0].IdPedido};Start-Sleep -Seconds 13
$files=@(Get-ChildItem $outbox -Filter *.eml -ErrorAction SilentlyContinue);$ped=$files|Where-Object{(Get-Content -Raw $_.FullName) -match 'X-LavaFacil-Proposito: mensaje' -and (Get-Content -Raw $_.FullName) -match 'Monto' -and (Get-Content -Raw $_.FullName) -match 'Detalle'};$txt=if($ped){Get-Content -Raw $ped.FullName}else{''};C 'un EML PedidoCreado con HTML y texto' (@($ped).Count -eq 1 -and $txt -match 'text/plain' -and $txt -match 'text/html' -and $txt -match 'Monto' -and $txt -match 'Detalle' -and $txt -notmatch '(?i)(password|clave|token|secret)') "emlCount=$(@($ped).Count); html=$($txt -match 'text/html'); texto=$($txt -match 'text/plain'); monto=$($txt -match 'Monto'); detalle=$($txt -match 'Detalle'); secretos=$($txt -match '(?i)(password|clave|token|secret)')"
$q="SELECT IdPedido,Tipo,Estado,Intentos,Destino,DatosJson FROM dbo.CorreoEnvios WHERE IdPedido=$orderId FOR JSON AUTO;";Set-Content "$PSScriptRoot\pedido-query.sql" $q;& sqlcmd -S MADRENZO -d LavaFacil -E -C -h -1 -W -Q $q | Set-Content "$PSScriptRoot\pedido-query.json";$db=Get-Content "$PSScriptRoot\pedido-query.json" -Raw;C 'CorreoEnvios PedidoCreado Enviado' ($db -match 'PedidoCreado' -and $db -match 'Enviado' -and $db -match '"Intentos":0') "pedido=$orderId; $db"
$checks|ConvertTo-Json -Depth 5|Set-Content "$PSScriptRoot\resultado-web.json";$checks|Format-Table -AutoSize

